class VideoPopup{constructor(){this.root=document.getElementById("video-popup"),this.frame_box=this.root?this.root.querySelector(".video-popup-frame"):null,this.embed_url="https://www.youtube-nocookie.com/embed/kKZ37mUspvQ?autoplay=1&rel=0",this.onKeydown=this.onKeydown.bind(this)}bind(){this.root&&this.frame_box&&(document.querySelectorAll(".watch-video-btn").forEach(e=>{e.addEventListener("click",e=>{e.preventDefault(),this.open()})}),this.root.querySelector(".video-popup-backdrop")?.addEventListener("click",()=>{this.close()}),this.root.querySelector(".video-popup-close")?.addEventListener("click",()=>{this.close()}))}open(){if(!this.frame_box.querySelector("iframe")){const e=document.createElement("iframe");e.src=this.embed_url,e.title="Tesera trailer",e.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",e.allowFullscreen=!0,this.frame_box.appendChild(e)}this.root.classList.add("show"),this.root.setAttribute("aria-hidden","false"),document.body.classList.add("fixed"),document.addEventListener("keydown",this.onKeydown)}close(){this.root.classList.remove("show"),this.root.setAttribute("aria-hidden","true"),document.body.classList.remove("fixed"),document.removeEventListener("keydown",this.onKeydown),window.setTimeout(()=>{this.root.classList.contains("show")||(this.frame_box.innerHTML="")},400)}onKeydown(e){"Escape"===e.key&&this.close()}}document.addEventListener("DOMContentLoaded",()=>{(new VideoPopup).bind()});